  // Capture original text once. Every later switch translates from this snapshot,

  // never from the currently displayed language.

  const edwiseTextNodes = [];

  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);

  let textNode;

  while ((textNode = walker.nextNode())) {

    if (textNode.parentElement.closest("script,style,.language-switch")) continue;

    const raw = textNode.nodeValue;

    const trimmed = raw.trim();

    if (trimmed) edwiseTextNodes.push({node:textNode, raw, key:trimmed});

  }

  const edwiseH1 = document.querySelector(".hero h1");

  const edwiseH1Original = edwiseH1 ? edwiseH1.innerHTML : "";

  const edwiseH1Translations = {

    en: 'Your future begins with <em>the right education.</em>',

    ar: 'مستقبلك يبدأ بـ <em>التعليم الصحيح.</em>'

  };



  function edwiseSetLanguage(lang) {

    const selected = ["tr","en","ar"].includes(lang) ? lang : "tr";

    const dict = EDWISE_I18N[selected] || {};

    edwiseTextNodes.forEach(({node,raw,key}) => {

      if (selected === "tr") node.nodeValue = raw;

      else if (Object.prototype.hasOwnProperty.call(dict,key)) {

        const leading = raw.match(/^\s*/)[0];

        const trailing = raw.match(/\s*$/)[0];

        node.nodeValue = leading + dict[key] + trailing;

      } else node.nodeValue = raw;

    });

    if (edwiseH1) {

      edwiseH1.innerHTML = selected === "tr" ? edwiseH1Original : edwiseH1Translations[selected];

    }

    document.documentElement.lang = selected;

    document.documentElement.dir = selected === "ar" ? "rtl" : "ltr";

    document.body.dir = selected === "ar" ? "rtl" : "ltr";

    document.querySelectorAll(".lang-btn").forEach(button => {

      const active = button.dataset.lang === selected;

      button.classList.toggle("active", active);

      button.setAttribute("aria-pressed", active ? "true" : "false");

      button.setAttribute("aria-pressed", active ? "true" : "false");

    });

    try { localStorage.setItem("edwise-language", selected); } catch(error) {}

  }



  document.querySelectorAll(".lang-btn").forEach(button => {

    button.addEventListener("click", () => edwiseSetLanguage(button.dataset.lang));

  });

  let initialLanguage = "tr";

  try { initialLanguage = localStorage.getItem("edwise-language") || "tr"; } catch(error) {}

  edwiseSetLanguage(initialLanguage);



  const menuButton = document.querySelector('.menu');

  const siteMenu = document.querySelector('#site-menu');

  // Ziyaretçi ana menüsünde yalnızca ana gezinme bağlantıları bulunur.
  // CMS sayfaları otomatik olarak ana menüye eklenmez; ilgili içerik alanlarında
  // (Hizmet Yönetimi, Sayfa Yönetimi ve footer yasal bağlantıları) yönetilir.
  (function applyCoreMenuVisibility() {
    if (!siteMenu) return;
    fetch("/api/public-settings", { headers: { "Accept": "application/json" }, cache: "no-store" })
      .then(response => response.ok ? response.json() : null)
      .then(data => {
        if (!data || !data.success || !Array.isArray(data.menu)) return;
        const keyFor = link => {
          const path = new URL(link.href, location.origin).pathname;
          if (link.classList.contains("menu-contact")) return "contact-cta";
          if (path === "/" || path.endsWith("/index.html")) return "home";
          if (path.endsWith("/hizmetlerimiz.html")) return "services";
          if (path.endsWith("/hakkimizda.html")) return "about";
          if (path.endsWith("/basvuru.html")) return "apply";
          if (path.endsWith("/iletisim.html")) return "contact";
          return null;
        };
        siteMenu.querySelectorAll(":scope > a").forEach(link => {
          const key = keyFor(link);
          const setting = key && data.menu.find(item => item.key === key);
          if (setting) link.style.display = setting.visible === false ? "none" : "";
        });
      })
      .catch(error => console.warn("Menü ayarları yüklenemedi:", error));
  })();

  function setMenuOpen(open) {

    siteMenu.classList.toggle('open', open);

    menuButton.setAttribute('aria-expanded', open ? 'true' : 'false');

    menuButton.setAttribute('aria-label', open ? 'Menüyü kapat' : 'Menüyü aç');

  }

  menuButton.addEventListener('click', () => setMenuOpen(!siteMenu.classList.contains('open')));

  siteMenu.querySelectorAll('a').forEach(link => link.addEventListener('click', () => setMenuOpen(false)));

  document.addEventListener('click', event => {

    if (!siteMenu.contains(event.target) && !menuButton.contains(event.target)) setMenuOpen(false);

  });

  document.addEventListener('keydown', event => {

    if (event.key === 'Escape') setMenuOpen(false);

  });

  
  // CMS üzerinden yayımlanan ortak site tasarımını uygula.
  (async function applyPublishedSiteTheme(){
    try{
      const response=await fetch("/api/public-settings",{headers:{"Accept":"application/json"},cache:"no-store"});
      if(!response.ok)return;
      const data=await response.json();
      if(!data.success||!data.theme)return;
      const t=data.theme,root=document.documentElement;
      const setText=(selector,value)=>{if(typeof value==="string"&&value.trim())document.querySelectorAll(selector).forEach(el=>el.textContent=value);};
      setText(".hero .eyebrow",t.heroEyebrow);
      setText(".hero .hero-content h1",t.heroTitle);
      setText(".hero .hero-content > p",t.heroDescription);
      setText(".hero .hero-actions .btn:first-child",t.heroButton);
      setText(".home-about .section-head h2",t.surfaceTitle);
      setText(".home-about .section-head > p",t.surfaceDescription);
      setText("footer > span:nth-of-type(1)",t.footerText);
      if(/^#[0-9a-fA-F]{6}$/.test(t.primary||""))root.style.setProperty("--navy",t.primary);
      if(/^#[0-9a-fA-F]{6}$/.test(t.accent||""))root.style.setProperty("--gold",t.accent);
      if(/^#[0-9a-fA-F]{6}$/.test(t.surface||""))root.style.setProperty("--cream",t.surface);
      if(/^#[0-9a-fA-F]{6}$/.test(t.text||""))root.style.setProperty("--ink",t.text);
      if(/^#[0-9a-fA-F]{6}$/.test(t.header||"")){
        document.querySelectorAll("header").forEach(el=>el.style.backgroundColor=t.header);
        const menu=document.querySelector("header nav#site-menu");if(menu)menu.style.backgroundColor=t.header;
      }
      if(/^#[0-9a-fA-F]{6}$/.test(t.hero||"")){
        document.querySelectorAll(".hero").forEach(el=>el.style.background="linear-gradient(110deg,"+t.hero+"f2 0%,"+t.hero+"e8 55%,"+t.primary+"dd 100%)");
      }
      if(/^#[0-9a-fA-F]{6}$/.test(t.footer||""))document.querySelectorAll("footer").forEach(el=>el.style.backgroundColor=t.footer);
      if(["Inter","Arial","Georgia","'Times New Roman'","Verdana"].includes(t.font||"")){
        document.body.style.fontFamily=t.font+",ui-sans-serif,system-ui,sans-serif";
      }
      if(/^(0|[2-9]|1[0-8])px$/.test(t.buttonRadius||"")){
        document.querySelectorAll(".btn,.nav-cta,.btn-outline").forEach(el=>el.style.borderRadius=t.buttonRadius);
      }
    }catch(error){console.warn("Site tasarımı yüklenemedi:",error);}
  })();

/* EDWISE site-wide visitor chat */
(()=>{if(document.getElementById("edwiseChatBox"))return;const style=document.createElement("style");style.textContent=".edwise-chat-launch{position:fixed;right:22px;bottom:88px;z-index:1000;border:0;border-radius:30px;background:#6942c5;color:#fff;padding:14px 20px;font-weight:700;box-shadow:0 8px 25px #25133b40;cursor:pointer}.edwise-chat-box{position:fixed;right:22px;bottom:145px;z-index:1001;width:min(360px,calc(100vw - 28px));height:440px;background:#fff;color:#241b35;border:1px solid #ddd3ee;border-radius:16px;box-shadow:0 18px 45px #24133a35;display:none;overflow:hidden}.edwise-chat-box.open{display:flex;flex-direction:column}.edwise-chat-head{padding:15px;background:#39216f;color:#fff;display:flex;justify-content:space-between;align-items:center}.edwise-chat-head button{border:0;background:transparent;color:#fff;font-size:22px;cursor:pointer}.edwise-chat-log{flex:1;overflow:auto;padding:12px;background:#faf9fd}.edwise-chat-bubble{max-width:88%;padding:9px 11px;border-radius:12px;margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.edwise-chat-bubble.visitor{margin-left:auto;background:#e9e0ff}.edwise-chat-bubble.admin{background:#eeeef3}.edwise-chat-form{display:flex;gap:7px;padding:10px;border-top:1px solid #eee}.edwise-chat-form input{min-width:0;flex:1;border:1px solid #d8d0e5;border-radius:9px;padding:10px}.edwise-chat-form button{border:0;border-radius:9px;background:#6942c5;color:white;padding:0 14px}";document.head.appendChild(style);document.body.insertAdjacentHTML("beforeend",'<button class="edwise-chat-launch" id="edwiseChatLaunch" type="button">✉ Bize mesaj gönder</button><section class="edwise-chat-box" id="edwiseChatBox" aria-label="EDWISE canlı mesajlaşma"><div class="edwise-chat-head"><div><b>EDWISE Destek</b><small style="display:block;opacity:.8">Mesajınızı bize iletin</small></div><button id="edwiseChatClose" type="button" aria-label="Kapat">×</button></div><div class="edwise-chat-log" id="edwiseChatLog"><p>Merhaba! EDWISE hakkında sorularınızı buradan iletebilirsiniz.</p></div><form class="edwise-chat-form" id="edwiseChatForm"><input id="edwiseChatInput" maxlength="1000" placeholder="Mesajınızı yazın..." required><button type="submit">Gönder</button></form></section>');const box=document.getElementById("edwiseChatBox"),launch=document.getElementById("edwiseChatLaunch"),log=document.getElementById("edwiseChatLog"),form=document.getElementById("edwiseChatForm"),input=document.getElementById("edwiseChatInput");let key=localStorage.getItem("edwise_chat_key");if(!key){key=crypto.randomUUID().replace(/-/g,"");localStorage.setItem("edwise_chat_key",key)}let id=Number(localStorage.getItem("edwise_chat_id"))||null,poll=null;function add(m){const el=document.createElement("div");el.className="edwise-chat-bubble "+(m.sender==="visitor"?"visitor":"admin");el.textContent=m.body;log.appendChild(el);log.scrollTop=log.scrollHeight;}async function refresh(){if(!id)return;try{const r=await fetch("/api/chat?id="+id+"&key="+encodeURIComponent(key));const d=await r.json();if(d.success){log.innerHTML="";(d.messages||[]).forEach(add);}}catch{}}launch.addEventListener("click",()=>{box.classList.add("open");launch.style.display="none";refresh();poll=setInterval(refresh,6000)});document.getElementById("edwiseChatClose").addEventListener("click",()=>{box.classList.remove("open");launch.style.display="block";clearInterval(poll)});form.addEventListener("submit",async e=>{e.preventDefault();const body=input.value.trim();if(!body)return;try{const r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,key,body,name:"Site ziyaretçisi"})});const d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||"Mesaj gönderilemedi.");id=d.id||id;localStorage.setItem("edwise_chat_id",id);input.value="";await refresh();}catch(err){alert(err.message)}});})();
